function.arguments:
{"query": "SELECT DISTINCT ?film ?character ?charName WHERE {
  ns:m.04f1s6 ns:film.actor.film ?film .
  ?film ns:film.performance.character ?character .
  OPTIONAL { ?character rdfs:label ?charName . }
  OPTIONAL { ?character ns:type.object.name ?charName . }
  FILTER(CONTAINS(LCASE(STR(?charName)), "luke") || CONTAINS(LCASE(STR(?charName)), "castelland"))
}", "question": "What film with character Luke Castelland does Logan Lerman play in?"}

{"query": "SELECT DISTINCT ?film WHERE {
  ns:m.04f1s6 ns:film.actor.film ?film .
  ?film ns:film.performance.character ?character .
  ?character rdfs:label ?charName .
  FILTER(LCASE(STR(?charName)) = "luke chandler")
}", "question": "What film with character Luke Castelland does Logan Lerman play in?"}

